import React, { useState, useRef, useEffect, useCallback } from 'react';
import { Bold, Italic, Underline, AlignLeft, AlignCenter, AlignRight, RotateCcw, RotateCw, List, Save, BookOpen } from 'lucide-react';
import { saveCV, getCV } from '../services/firebase';

const CVEditor: React.FC = () => {
  const editorRef = useRef<HTMLDivElement>(null);
  const [lastSaved, setLastSaved] = useState<string>('');

  // Reference Doc State
  const [showDoc, setShowDoc] = useState(false);

  // Initial Load from Firestore
  useEffect(() => {
    const loadContent = async () => {
        const content = await getCV();
        if (content && editorRef.current) {
            editorRef.current.innerHTML = content;
            setLastSaved('Loaded from Cloud');
        } else if (editorRef.current && !editorRef.current.innerHTML.trim()) {
            // Default Content if nothing in DB
            editorRef.current.innerHTML = `
            <h1 style="font-size: 2em; font-weight: bold; margin-bottom: 0.5em; color: #1d1d1f;">Senior UX Designer</h1>
            <p><strong>Summary</strong></p>
            <p>Strategic and human-centered Senior UX Designer with 7+ years of experience transforming complex financial and insurance problems into intuitive digital solutions.</p>
            <br>
            <p><strong>Experience</strong></p>
            <p><strong>Lead Product Designer | Intact Insurance</strong></p>
            <ul>
                <li>Spearheaded the redesign of the claims portal, reducing processing time by 30%.</li>
                <li>Mentored junior designers and established the 'Trove' design system.</li>
            </ul>
            `;
        }
    };
    loadContent();
  }, []);

  const saveContent = useCallback(async () => {
    if (editorRef.current) {
        const html = editorRef.current.innerHTML;
        // Save to Firestore
        await saveCV(html);
        const now = new Date();
        setLastSaved(now.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }));
    }
  }, []);

  // Debounced auto-save
  useEffect(() => {
      const handleInput = () => {
          const timeoutId = setTimeout(() => {
              saveContent();
          }, 1000);
          return () => clearTimeout(timeoutId);
      };

      const el = editorRef.current;
      const rawInputHandler = () => {
         handleInput();
      };

      el?.addEventListener('input', rawInputHandler);
      return () => el?.removeEventListener('input', rawInputHandler);
  }, [saveContent]);

  const execCmd = (command: string, value: string | undefined = undefined) => {
    document.execCommand(command, false, value);
    if (editorRef.current) editorRef.current.focus();
    saveContent();
  };

  return (
    <div className={`flex h-[calc(100vh-140px)] gap-6 mx-auto relative px-6 pb-6 transition-all duration-300 ${showDoc ? 'w-full max-w-none' : 'max-w-[1400px]'}`}>

        {/* Editor Container - Apple Card Style */}
        <div className="flex-1 flex flex-col bg-white rounded-[24px] shadow-sm overflow-hidden border border-black/5 transition-all duration-300">

            {/* Toolbar */}
            <div className="h-14 border-b border-[#f5f5f7] flex items-center px-4 justify-between bg-white z-10">
                <div className="flex items-center gap-1" role="toolbar" aria-label="Formatting Controls">
                    <button onClick={() => execCmd('undo')} className="p-2 hover:bg-[#f5f5f7] rounded-md text-[#86868b] hover:text-[#1d1d1f] transition-colors" title="Undo"><RotateCcw size={16} /></button>
                    <button onClick={() => execCmd('redo')} className="p-2 hover:bg-[#f5f5f7] rounded-md text-[#86868b] hover:text-[#1d1d1f] transition-colors" title="Redo"><RotateCw size={16} /></button>

                    <div className="w-px h-5 bg-[#e8e8ed] mx-2"></div>

                    <button onClick={() => execCmd('bold')} className="p-2 hover:bg-[#f5f5f7] rounded-md text-[#86868b] hover:text-[#1d1d1f] font-bold" title="Bold"><Bold size={16} /></button>
                    <button onClick={() => execCmd('italic')} className="p-2 hover:bg-[#f5f5f7] rounded-md text-[#86868b] hover:text-[#1d1d1f] italic" title="Italic"><Italic size={16} /></button>
                    <button onClick={() => execCmd('underline')} className="p-2 hover:bg-[#f5f5f7] rounded-md text-[#86868b] hover:text-[#1d1d1f] underline" title="Underline"><Underline size={16} /></button>

                    <div className="w-px h-5 bg-[#e8e8ed] mx-2"></div>

                    <button onClick={() => execCmd('justifyLeft')} className="p-2 hover:bg-[#f5f5f7] rounded-md text-[#86868b] hover:text-[#1d1d1f]" title="Align Left"><AlignLeft size={16} /></button>
                    <button onClick={() => execCmd('justifyCenter')} className="p-2 hover:bg-[#f5f5f7] rounded-md text-[#86868b] hover:text-[#1d1d1f]" title="Align Center"><AlignCenter size={16} /></button>
                    <button onClick={() => execCmd('insertUnorderedList')} className="p-2 hover:bg-[#f5f5f7] rounded-md text-[#86868b] hover:text-[#1d1d1f]" title="List"><List size={16} /></button>
                </div>

                <div className="flex items-center gap-3">
                     {/* Reference Toggle */}
                    <button
                        onClick={() => setShowDoc(!showDoc)}
                        className={`p-2 rounded-full transition-all border flex items-center gap-2 px-4 text-xs font-semibold ${showDoc ? 'bg-[#1d1d1f] text-white border-transparent' : 'bg-white text-[#86868b] border-[#e8e8ed] hover:border-[#86868b] hover:text-[#1d1d1f]'}`}
                        title="Reference Document"
                    >
                        <BookOpen size={16} /> {showDoc ? 'Hide Reference' : 'Show Reference'}
                    </button>

                     <div className="text-[10px] font-medium text-[#86868b] bg-[#f5f5f7] px-3 py-1.5 rounded-full">
                        {lastSaved ? `Saved ${lastSaved}` : 'Unsaved'}
                    </div>
                </div>
            </div>

            {/* Editor Canvas Container */}
            <div className="flex-1 overflow-y-auto bg-[#F5F5F7] flex relative">

                {/* Reference Doc (Left) */}
                {showDoc && (
                    <div className="w-1/2 h-full border-r border-[#e8e8ed] bg-white hidden lg:block animate-in slide-in-from-left-4 duration-300">
                        <iframe 
                            src="https://docs.google.com/document/d/1RcERxf9--nMGdxXTHAt4q35yynk39Aqk31AqSuG02G4/preview" 
                            className="w-full h-full" 
                            title="Reference CV"
                        ></iframe>
                    </div>
                )}

                {/* Paper */}
                <div className={`flex-1 flex justify-center p-8 transition-all ${showDoc ? 'bg-[#f0f0f2]' : ''}`}>
                     <div 
                        ref={editorRef}
                        contentEditable
                        role="textbox"
                        aria-multiline="true"
                        className={`w-full h-max bg-white shadow-sm border border-[#e8e8ed] p-[72px] outline-none text-[#1d1d1f] font-sans text-lg leading-[1.6] transition-all rounded-sm mb-16 ${showDoc ? 'max-w-full' : 'max-w-[850px]'}`}
                    />
                </div>
            </div>
        </div>
    </div>
  );
};

