import React, { useState } from 'react';
import { Job } from '../types';
import JobCard from './JobCard';
import { Bookmark, Send, Users, Trophy } from 'lucide-react';

interface KanbanBoardProps {
  jobs: Job[];
  onGenerateKit: (job: Job) => void;
  onToggleStatus: (id: string, status: Job['status']) => void;
  onDelete: (id: string) => void;
  onOpenDetail: (job: Job) => void;
  onOpenAddModal: () => void;
}

const KanbanBoard: React.FC<KanbanBoardProps> = ({ jobs, onGenerateKit, onToggleStatus, onDelete, onOpenDetail, onOpenAddModal }) => {
  const [draggedJobId, setDraggedJobId] = useState<string | null>(null);

  const columns: { id: Job['status'], title: string, icon: React.ReactNode, count: number }[] = [
      { id: 'saved', title: 'Saved', icon: <Bookmark size={14} />, count: jobs.filter(j => j.status === 'saved').length },
      { id: 'applied', title: 'Applied', icon: <Send size={14} />, count: jobs.filter(j => j.status === 'applied').length },
      { id: 'interview', title: 'Interview', icon: <Users size={14} />, count: jobs.filter(j => j.status === 'interview').length },
      { id: 'offer', title: 'Offer', icon: <Trophy size={14} />, count: jobs.filter(j => j.status === 'offer').length },
  ];

  const handleDragStart = (e: React.DragEvent, id: string) => {
      setDraggedJobId(id);
      e.dataTransfer.effectAllowed = "move";
  };

  const handleDragOver = (e: React.DragEvent) => {
      e.preventDefault(); 
      e.dataTransfer.dropEffect = "move";
  };

  const handleDrop = (e: React.DragEvent, status: Job['status']) => {
      e.preventDefault();
      if (draggedJobId) {
          onToggleStatus(draggedJobId, status);
          setDraggedJobId(null);
      }
  };

  return (
    // Removed -ml-6 because the parent container is w-full (no padding).
    // The spacer handles the indentation.
    <div className="flex gap-4 overflow-x-auto w-full pb-8 pt-2 items-start h-full scrollbar-hide">

      {/* Spacer to align with "Pipeline" title (max-w-[1024px] px-6) */}
      <div className="shrink-0 w-[calc(50vw-512px+24px)] hidden min-[1024px]:block"></div>
      <div className="shrink-0 w-6 min-[1024px]:hidden"></div>

      {columns.map(col => {
            const colJobs = jobs.filter(j => j.status === col.id);
            return (
                <div 
                    key={col.id}
                    className="flex flex-col min-w-[320px] max-w-[320px] bg-[#E8E8ED]/50 dark:bg-[#1C1C1E]/50 rounded-[16px] p-2 h-full border border-white/50 dark:border-white/5 backdrop-blur-sm"
                    onDragOver={handleDragOver}
                    onDrop={(e) => handleDrop(e, col.id)}
                >
                    <div className="flex items-center justify-between p-3 mb-1 shrink-0">
                        <h3 className="font-semibold text-[13px] text-[#1d1d1f] dark:text-[#f5f5f7] flex items-center gap-2">
                            {col.icon} {col.title}
                        </h3>
                        <span className="text-[10px] font-bold text-[#86868b] dark:text-[#98989D] bg-white dark:bg-[#2C2C2E] px-2 py-0.5 rounded-full shadow-sm">{col.count}</span>
                    </div>

                    <div className="flex-1 space-y-2 overflow-y-auto px-1 pb-4 custom-scrollbar">
                        {colJobs.length === 0 && (
                            <div className="h-20 border-2 border-dashed border-[#d2d2d7]/50 dark:border-[#38383A] rounded-lg flex items-center justify-center">
                                <span className="text-[10px] text-[#86868b] dark:text-[#98989D] font-medium">Empty</span>
                            </div>
                        )}
                        {colJobs.map(job => (
                            <div
                                key={job.id}
                                draggable
                                onDragStart={(e) => handleDragStart(e, job.id)}
                                className="cursor-grab active:cursor-grabbing hover:scale-[1.02] transition-transform"
                            >
                                <JobCard 
                                    job={job} 
                                    onOpenDetail={onOpenDetail}
                                    onToggleStatus={(id, st) => onToggleStatus(id, st)} 
                                    onDelete={onDelete} 
                                    isKanban={true}
                                />
                            </div>
                        ))}
                    </div>
                </div>
            );
      })}

      {/* Trailing padding for scroll */}
      <div className="shrink-0 w-6"></div>
    </div>
  );
};

export default KanbanBoard;

import React from 'react';
import { PieChart, Pie, Cell, Tooltip, ResponsiveContainer } from 'recharts';
import { Job } from '../types';

interface StatsPanelProps {
  jobs: Job[]; 
  selectedIndustry: string | null;
  onSelectIndustry: (industry: string | null) => void;
}

// Apple Data Colors
const COLORS = [
  '#0071e3', // Blue
  '#ff2d55', // Pink
  '#ffcc00', // Yellow
  '#34c759', // Green
  '#af52de', // Purple
  '#5856d6'  // Indigo
];

const StatsPanel: React.FC<StatsPanelProps> = ({ jobs, selectedIndustry, onSelectIndustry }) => {
  const getIndustry = (job: Job): string => {
    if (job.analysis?.industry && job.analysis.industry !== "Other") {
        return job.analysis.industry;
    }
    const text = (job.company + " " + job.title + " " + (job.summary || "")).toLowerCase();
    if (text.match(/bank|finance|wealth|fintech/)) return 'Fintech';
    if (text.match(/insurance|underwrit/)) return 'Insurance';
    if (text.match(/gov|public|council|nhs/)) return 'Public Sector';
    if (text.match(/agency|studio/)) return 'Agency';
    return 'Tech';
  };

  const industryCounts = jobs.reduce((acc, job) => {
    const industry = getIndustry(job);
    acc[industry] = (acc[industry] || 0) + 1;
    return acc;
  }, {} as Record<string, number>);

  const data = Object.entries(industryCounts)
    .map(([name, value]) => ({ name, value: value as number }))
    .filter((item) => item.value > 0)
    .sort((a, b) => b.value - a.value);

  const totalJobs = data.reduce((sum, item) => sum + item.value, 0);

  if (totalJobs === 0) return null;

  return (
    <div>
      <div className="flex items-center justify-between mb-3">
        <h3 className="text-[11px] font-bold text-[#86868b] dark:text-[#98989D] uppercase tracking-wider">Breakdown</h3>
        {selectedIndustry && (
            <button 
                onClick={() => onSelectIndustry(null)}
                className="text-[10px] font-bold text-[#0071e3] dark:text-[#0A84FF] hover:underline"
            >
                Reset
            </button>
        )}
      </div>

      {/* Reduced Height for Compact View */}
      <div className="h-[120px] relative mb-4">
        <ResponsiveContainer width="100%" height="100%">
          <PieChart>
            <Pie 
                data={data} 
                cx="50%" 
                cy="50%" 
                innerRadius={35} 
                outerRadius={55} 
                paddingAngle={4} 
                dataKey="value" 
                stroke="none" 
                cornerRadius={4}
                onClick={(data) => {
                    const newSelection = selectedIndustry === data.name ? null : data.name;
                    onSelectIndustry(newSelection);
                }}
            >
              {data.map((entry, index) => (
                <Cell 
                    key={`cell-${index}`} 
                    fill={COLORS[index % COLORS.length]} 
                    opacity={selectedIndustry && selectedIndustry !== entry.name ? 0.3 : 1}
                    style={{ outline: 'none', transition: 'all 0.3s ease', cursor: 'pointer' }}
                />
              ))}
            </Pie>
            <Tooltip 
              contentStyle={{ borderRadius: '12px', border: 'none', padding: '8px 12px', fontSize: '11px', boxShadow: '0 4px 20px rgba(0,0,0,0.1)', background: '#fff' }}
              itemStyle={{ color: '#1d1d1f', fontWeight: 600 }}
            />
          </PieChart>
        </ResponsiveContainer>

        <div className="absolute inset-0 flex flex-col items-center justify-center pointer-events-none">
             <span className="text-2xl font-bold text-[#1d1d1f] dark:text-[#f5f5f7] tracking-tight">{selectedIndustry ? data.find(d => d.name === selectedIndustry)?.value : totalJobs}</span>
        </div>
      </div>

      <div className="space-y-1">
        {data.slice(0, 5).map((entry, index) => {
          const isSelected = selectedIndustry === entry.name;
          return (
            <button
                key={entry.name} 
                onClick={() => onSelectIndustry(isSelected ? null : entry.name)}
                className={`w-full flex items-center justify-between text-[11px] cursor-pointer px-2.5 py-1.5 rounded-lg transition-colors ${isSelected ? 'bg-[#F5F5F7] dark:bg-[#2C2C2E] font-semibold text-[#0071e3] dark:text-[#0A84FF]' : 'text-[#86868b] dark:text-[#98989D] hover:bg-[#F5F5F7] dark:hover:bg-[#2C2C2E]'}`}
            >
               <div className="flex items-center gap-2">
                 <div className="w-2 h-2 rounded-full" style={{ backgroundColor: COLORS[index % COLORS.length] }}></div>
                 <span className="truncate max-w-[140px]">{entry.name}</span>
               </div>
               <span>{entry.value}</span>
            </button>
          );
        })}
      </div>
    </div>
  );
};

export default StatsPanel;

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { Bold, Italic, Underline, AlignLeft, AlignCenter, AlignRight, RotateCcw, RotateCw, List, Save, BookOpen } from 'lucide-react';
import { saveCV, getCV } from '../services/firebase';

const CVEditor: React.FC = () => {
  const editorRef = useRef<HTMLDivElement>(null);
  const [lastSaved, setLastSaved] = useState<string>('');

  // Reference Doc State
  const [showDoc, setShowDoc] = useState(false);

  // Initial Load from Firestore
  useEffect(() => {
    const loadContent = async () => {
        const content = await getCV();
        if (content && editorRef.current) {
            editorRef.current.innerHTML = content;
            setLastSaved('Loaded from Cloud');
        } else if (editorRef.current && !editorRef.current.innerHTML.trim()) {
            // Default Content if nothing in DB
            editorRef.current.innerHTML = `
            <h1 style="font-size: 2em; font-weight: bold; margin-bottom: 0.5em; color: #1d1d1f;">Senior UX Designer</h1>
            <p><strong>Summary</strong></p>
            <p>Strategic and human-centered Senior UX Designer with 7+ years of experience transforming complex financial and insurance problems into intuitive digital solutions.</p>
            <br>
            <p><strong>Experience</strong></p>
            <p><strong>Lead Product Designer | Intact Insurance</strong></p>
            <ul>
                <li>Spearheaded the redesign of the claims portal, reducing processing time by 30%.</li>
                <li>Mentored junior designers and established the 'Trove' design system.</li>
            </ul>
            `;
        }
    };
    loadContent();
  }, []);

  const saveContent = useCallback(async () => {
    if (editorRef.current) {
        const html = editorRef.current.innerHTML;
        // Save to Firestore
        await saveCV(html);
        const now = new Date();
        setLastSaved(now.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }));
    }
  }, []);

  // Debounced auto-save
  useEffect(() => {
      const handleInput = () => {
          const timeoutId = setTimeout(() => {
              saveContent();
          }, 1000);
          return () => clearTimeout(timeoutId);
      };

      const el = editorRef.current;
      const rawInputHandler = () => {
         handleInput();
      };

      el?.addEventListener('input', rawInputHandler);
      return () => el?.removeEventListener('input', rawInputHandler);
  }, [saveContent]);

  const execCmd = (command: string, value: string | undefined = undefined) => {
    document.execCommand(command, false, value);
    if (editorRef.current) editorRef.current.focus();
    saveContent();
  };

  return (
    <div className={`flex h-[calc(100vh-140px)] gap-6 mx-auto relative px-6 pb-6 transition-all duration-500 ease-out ${showDoc ? 'w-full max-w-none' : 'max-w-[1400px]'}`}>

        {/* Editor Container - Apple Card Style */}
        <div className="flex-1 flex flex-col bg-white dark:bg-[#1C1C1E] rounded-[24px] shadow-sm overflow-hidden border border-black/5 dark:border-white/10 transition-all duration-300">

            {/* Toolbar */}
            <div className="h-14 border-b border-[#f5f5f7] dark:border-[#38383A] flex items-center px-4 justify-between bg-white/80 dark:bg-[#1C1C1E]/80 backdrop-blur-md z-10 sticky top-0 transition-colors">
                <div className="flex items-center gap-1" role="toolbar" aria-label="Formatting Controls">
                    <button onClick={() => execCmd('undo')} className="p-2 hover:bg-[#f5f5f7] dark:hover:bg-[#2C2C2E] rounded-md text-[#86868b] dark:text-[#98989D] hover:text-[#1d1d1f] dark:hover:text-white transition-colors" title="Undo"><RotateCcw size={16} /></button>
                    <button onClick={() => execCmd('redo')} className="p-2 hover:bg-[#f5f5f7] dark:hover:bg-[#2C2C2E] rounded-md text-[#86868b] dark:text-[#98989D] hover:text-[#1d1d1f] dark:hover:text-white transition-colors" title="Redo"><RotateCw size={16} /></button>

                    <div className="w-px h-5 bg-[#e8e8ed] dark:bg-[#38383A] mx-2"></div>

                    <button onClick={() => execCmd('bold')} className="p-2 hover:bg-[#f5f5f7] dark:hover:bg-[#2C2C2E] rounded-md text-[#86868b] dark:text-[#98989D] hover:text-[#1d1d1f] dark:hover:text-white font-bold" title="Bold"><Bold size={16} /></button>
                    <button onClick={() => execCmd('italic')} className="p-2 hover:bg-[#f5f5f7] dark:hover:bg-[#2C2C2E] rounded-md text-[#86868b] dark:text-[#98989D] hover:text-[#1d1d1f] dark:hover:text-white italic" title="Italic"><Italic size={16} /></button>
                    <button onClick={() => execCmd('underline')} className="p-2 hover:bg-[#f5f5f7] dark:hover:bg-[#2C2C2E] rounded-md text-[#86868b] dark:text-[#98989D] hover:text-[#1d1d1f] dark:hover:text-white underline" title="Underline"><Underline size={16} /></button>

                    <div className="w-px h-5 bg-[#e8e8ed] dark:bg-[#38383A] mx-2"></div>

                    <button onClick={() => execCmd('justifyLeft')} className="p-2 hover:bg-[#f5f5f7] dark:hover:bg-[#2C2C2E] rounded-md text-[#86868b] dark:text-[#98989D] hover:text-[#1d1d1f] dark:hover:text-white" title="Align Left"><AlignLeft size={16} /></button>
                    <button onClick={() => execCmd('justifyCenter')} className="p-2 hover:bg-[#f5f5f7] dark:hover:bg-[#2C2C2E] rounded-md text-[#86868b] dark:text-[#98989D] hover:text-[#1d1d1f] dark:hover:text-white" title="Align Center"><AlignCenter size={16} /></button>
                    <button onClick={() => execCmd('insertUnorderedList')} className="p-2 hover:bg-[#f5f5f7] dark:hover:bg-[#2C2C2E] rounded-md text-[#86868b] dark:text-[#98989D] hover:text-[#1d1d1f] dark:hover:text-white" title="List"><List size={16} /></button>
                </div>

                <div className="flex items-center gap-3">
                     {/* Reference Toggle */}
                    <button
                        onClick={() => setShowDoc(!showDoc)}
                        className={`h-8 px-4 rounded-full transition-all border flex items-center gap-2 text-xs font-semibold ${showDoc ? 'bg-[#1d1d1f] dark:bg-white text-white dark:text-black border-transparent shadow-md' : 'bg-white dark:bg-[#2C2C2E] text-[#86868b] dark:text-[#98989D] border-[#e8e8ed] dark:border-[#38383A] hover:border-[#86868b] dark:hover:border-[#98989D] hover:text-[#1d1d1f] dark:hover:text-white'}`}
                        title="Reference Document"
                    >
                        <BookOpen size={14} /> {showDoc ? 'Hide Ref' : 'Show Ref'}
                    </button>

                     <div className="text-[10px] font-medium text-[#86868b] dark:text-[#98989D] bg-[#f5f5f7] dark:bg-[#2C2C2E] px-3 py-1.5 rounded-full border border-black/5 dark:border-white/5">
                        {lastSaved ? `Saved ${lastSaved}` : 'Unsaved'}
                    </div>
                </div>
            </div>

            {/* Editor Canvas Container */}
            <div className="flex-1 overflow-y-auto bg-[#F5F5F7] dark:bg-[#000000] flex relative custom-scrollbar transition-colors">

                {/* Reference Doc (Left) */}
                {showDoc && (
                    <div className="w-1/2 h-full border-r border-[#e8e8ed] dark:border-[#38383A] bg-white dark:bg-[#1C1C1E] hidden lg:block animate-in slide-in-from-left-4 duration-500 ease-out">
                        <iframe 
                            src="https://docs.google.com/document/d/1RcERxf9--nMGdxXTHAt4q35yynk39Aqk31AqSuG02G4/preview" 
                            className="w-full h-full border-none" 
                            title="Reference CV"
                        ></iframe>
                    </div>
                )}

                {/* Paper - Always White for Realism */}
                <div className={`flex-1 flex justify-center p-8 transition-all duration-500 ${showDoc ? 'bg-[#f0f0f2] dark:bg-[#121212]' : ''}`}>
                     <div 
                        ref={editorRef}
                        contentEditable
                        role="textbox"
                        aria-multiline="true"
                        className={`w-full h-max bg-white shadow-[0_2px_15px_-3px_rgba(0,0,0,0.07),0_10px_20px_-2px_rgba(0,0,0,0.04)] dark:shadow-[0_2px_15px_-3px_rgba(0,0,0,0.5)] border border-[#e8e8ed] p-[72px] outline-none text-[#1d1d1f] font-sans text-lg leading-[1.6] transition-all rounded-sm mb-16 ${showDoc ? 'max-w-full' : 'max-w-[850px]'}`}
                    />
                </div>
            </div>
        </div>
    </div>
  );
};

export default CVEditor;

import React, { useEffect, useState } from 'react';
import { X, ExternalLink, Briefcase, Zap, FileText, Sparkles, Edit2, Save, ChevronDown, RotateCw, TrendingUp, AlertTriangle } from 'lucide-react';
import { Job } from '../types';

interface JobDetailModalProps {
  isOpen: boolean;
  onClose: () => void;
  job: Job | null;
  onGenerateKit: (job: Job) => void;
  initialTab?: 'brief' | 'strategy';
  onUpdateJob?: (job: Job) => void;
  onReAnalyze?: (job: Job) => Promise<void>;
}

const JobDetailModal: React.FC<JobDetailModalProps> = ({ isOpen, onClose, job, onGenerateKit, initialTab = 'brief', onUpdateJob, onReAnalyze }) => {
  const [activeTab, setActiveTab] = useState<'brief' | 'strategy'>(initialTab);
  const [isEditingSummary, setIsEditingSummary] = useState(false);
  const [editedSummary, setEditedSummary] = useState('');

  // Title Editing
  const [isEditingTitle, setIsEditingTitle] = useState(false);
  const [editedTitle, setEditedTitle] = useState('');

  // Company Editing
  const [isEditingCompany, setIsEditingCompany] = useState(false);
  const [editedCompany, setEditedCompany] = useState('');

  // Location Editing
  const [isEditingLocation, setIsEditingLocation] = useState(false);
  const [editedLocation, setEditedLocation] = useState('');

  // Posted Date Editing
  const [isEditingPostedDate, setIsEditingPostedDate] = useState(false);
  const [editedPostedDate, setEditedPostedDate] = useState('');

  // URL Editing
  const [isEditingUrl, setIsEditingUrl] = useState(false);
  const [editedUrl, setEditedUrl] = useState('');

  // Re-Analyze State
  const [isAnalyzing, setIsAnalyzing] = useState(false);

  useEffect(() => {
    setActiveTab(initialTab);
  }, [initialTab, isOpen, job]);

  useEffect(() => {
    if (job) {
        setEditedSummary(job.summary || '');
        setEditedTitle(job.title || '');
        setEditedCompany(job.company || '');
        setEditedLocation(job.location || '');
        setEditedPostedDate(job.postedDate || '');
        setEditedUrl(job.url === 'Manual Entry' ? '' : (job.url || ''));
    }
  }, [job]);

  useEffect(() => {
    if (isOpen) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = 'unset';
    }
    return () => { document.body.style.overflow = 'unset'; };
  }, [isOpen]);

  if (!isOpen || !job) return null;

  const analysis = job.analysis;

  const getAbsoluteUrl = (url?: string) => {
      if (!url || url === 'Manual Entry') return null;
      return url.startsWith('http') ? url : `https://${url}`;
  };

  const applyUrl = getAbsoluteUrl(job.url) || `https://www.google.com/search?q=${encodeURIComponent(`${job.title} ${job.company} jobs`)}`;

  const handleSaveDescription = () => {
      if (onUpdateJob) {
          onUpdateJob({ ...job, summary: editedSummary });
          setIsEditingSummary(false);
      }
  };

  const handleSaveTitle = () => {
      if (onUpdateJob && editedTitle.trim() !== job.title) {
          onUpdateJob({ ...job, title: editedTitle });
      }
      setIsEditingTitle(false);
  };

  const handleSaveCompany = () => {
      if (onUpdateJob && editedCompany.trim() !== job.company) {
          onUpdateJob({ ...job, company: editedCompany });
      }
      setIsEditingCompany(false);
  };

  const handleSaveLocation = () => {
      if (onUpdateJob && editedLocation.trim() !== job.location) {
          onUpdateJob({ ...job, location: editedLocation });
      }
      setIsEditingLocation(false);
  };

  const handleSavePostedDate = () => {
      if (onUpdateJob && editedPostedDate.trim() !== job.postedDate) {
          onUpdateJob({ ...job, postedDate: editedPostedDate });
      }
      setIsEditingPostedDate(false);
  };

  const handleSaveUrl = () => {
      if (onUpdateJob && editedUrl.trim() !== job.url) {
          const finalUrl = editedUrl.trim() || 'Manual Entry';
          onUpdateJob({ ...job, url: finalUrl });
      }
      setIsEditingUrl(false);
  };

  const handleStatusChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
      if (onUpdateJob) {
          onUpdateJob({ ...job, status: e.target.value as Job['status'] });
      }
  };

  const handleReAnalyzeClick = async () => {
      if (onReAnalyze) {
          setIsAnalyzing(true);
          await onReAnalyze(job);
          setIsAnalyzing(false);
      }
  };

  const isValidAttribute = (attr?: string) => {
      if (!attr) return false;
      const lower = attr.toLowerCase();
      return lower !== 'unspecified' && lower !== 'unknown' && lower !== 'n/a' && attr.trim() !== '';
  };

  return (
    <div 
        className="fixed inset-0 z-[100] flex items-center justify-center p-4 sm:p-6 transition-all duration-300"
        role="dialog"
        aria-modal="true"
    >
      {/* Darkened Backdrop */}
      <div className="absolute inset-0 bg-black/60 backdrop-blur-sm" onClick={onClose}></div>

      {/* Surface - Clean Apple Style */}
      <div className="relative bg-white dark:bg-[#1C1C1E] w-full max-w-5xl h-[90vh] flex flex-col shadow-2xl rounded-[32px] overflow-hidden animate-in fade-in zoom-in-95 duration-200 border border-transparent dark:border-white/10 transition-colors">

        {/* Header - Minimalist */}
        <div className="flex items-start justify-between px-8 py-8 shrink-0 bg-white dark:bg-[#1C1C1E] z-10 transition-colors">
           <div className="flex-1 mr-8">
                {/* Title Editing */}
                {isEditingTitle ? (
                    <input 
                    type="text" 
                    value={editedTitle}
                    onChange={(e) => setEditedTitle(e.target.value)}
                    onBlur={handleSaveTitle}
                    onKeyDown={(e) => e.key === 'Enter' && handleSaveTitle()}
                    className="text-3xl font-semibold text-[#1d1d1f] dark:text-white w-full outline-none bg-transparent p-0 border-b border-[#0071e3] dark:border-[#0A84FF]"
                    autoFocus
                    />
                ) : (
                    <h2 
                    onClick={() => setIsEditingTitle(true)}
                    className="text-3xl font-semibold text-[#1d1d1f] dark:text-white leading-tight cursor-pointer hover:text-[#0071e3] dark:hover:text-[#0A84FF] transition-colors"
                    >
                    {job.title}
                    </h2>
                )}

                {/* Company & Location Subtitle */}
                <div className="mt-2 flex items-center gap-2 text-lg text-[#86868b] dark:text-[#98989D] font-medium">
                    {isEditingCompany ? (
                        <input 
                            type="text" 
                            value={editedCompany}
                            onChange={(e) => setEditedCompany(e.target.value)}
                            onBlur={handleSaveCompany}
                            className="border-b border-[#0071e3] dark:border-[#0A84FF] outline-none bg-transparent w-40 text-[#1d1d1f] dark:text-white"
                        />
                    ) : (
                        <span onClick={() => setIsEditingCompany(true)} className="hover:text-[#0071e3] dark:hover:text-[#0A84FF] cursor-pointer transition-colors">{job.company}</span>
                    )}
                    <span>•</span>
                    <span>{job.location}</span>
                </div>
           </div>

           <button 
                onClick={onClose} 
                className="w-10 h-10 flex items-center justify-center bg-[#f5f5f7] dark:bg-[#2C2C2E] hover:bg-[#e8e8ed] dark:hover:bg-[#38383A] rounded-full text-[#1d1d1f] dark:text-white transition-colors"
           >
             <X size={20} />
           </button>
        </div>

        {/* Scrollable Content */}
        <div className="flex-1 overflow-y-auto custom-scrollbar px-8 pb-12">
            <div className="flex flex-col md:flex-row gap-12">

                {/* LEFT: Main Information */}
                <div className="flex-1 order-2 md:order-1">

                    {/* Tabs Pill */}
                    <div className="flex items-center gap-1 mb-8 bg-[#f5f5f7] dark:bg-[#2C2C2E] p-1 rounded-full w-fit">
                        <button 
                            onClick={() => setActiveTab('brief')} 
                            className={`px-5 py-2 rounded-full text-[13px] font-semibold transition-all ${activeTab === 'brief' ? 'bg-white dark:bg-[#1C1C1E] text-black dark:text-white shadow-sm' : 'text-[#86868b] dark:text-[#98989D] hover:text-[#1d1d1f] dark:hover:text-white'}`}
                        >
                            Overview
                        </button>
                        <button 
                            onClick={() => {
                                setActiveTab('strategy');
                                if (!analysis?.strategy) onGenerateKit(job);
                            }} 
                            className={`px-5 py-2 rounded-full text-[13px] font-semibold transition-all ${activeTab === 'strategy' ? 'bg-white dark:bg-[#1C1C1E] text-black dark:text-white shadow-sm' : 'text-[#86868b] dark:text-[#98989D] hover:text-[#1d1d1f] dark:hover:text-white'}`}
                        >
                            Strategy Kit
                        </button>
                    </div>

                    {activeTab === 'brief' ? (
                        <div className="animate-in fade-in slide-in-from-bottom-2 duration-300">
                            {/* Chips */}
                            <div className="mb-8 flex flex-wrap gap-2">
                                {analysis && analysis.isHighValue && (
                                     <span className="px-3 py-1 rounded-full text-[12px] font-semibold bg-[#E6F4EA] dark:bg-[#1e3a29] text-[#1e8e3e] dark:text-[#45D469]">High Value</span>
                                )}
                                {isValidAttribute(analysis?.industry) && (
                                    <span className="px-3 py-1 rounded-full text-[12px] font-semibold bg-[#E8F2FF] dark:bg-[#122438] text-[#0071e3] dark:text-[#409CFF]">{analysis?.industry}</span>
                                )}
                                {isValidAttribute(job.seniorityScore) && (
                                    <span className="px-3 py-1 bg-[#f5f5f7] dark:bg-[#2C2C2E] text-[#1d1d1f] dark:text-[#f5f5f7] rounded-full text-[12px] font-semibold">{job.seniorityScore}</span>
                                )}
                            </div>

                            {/* Verdict */}
                            {analysis && (
                                <div className="mb-8">
                                    <h4 className="text-[11px] font-bold text-[#86868b] dark:text-[#98989D] uppercase tracking-wider mb-2">AI Analysis</h4>
                                    <p className="text-[18px] text-[#1d1d1f] dark:text-[#f5f5f7] font-medium leading-relaxed">{analysis.verdict}</p>
                                </div>
                            )}

                            {/* Description */}
                            <div className="mb-10">
                                <div className="flex items-center justify-between mb-3">
                                    <h4 className="text-[11px] font-bold text-[#86868b] dark:text-[#98989D] uppercase tracking-wider">Job Description</h4>
                                    {!isEditingSummary ? (
                                        <button onClick={() => setIsEditingSummary(true)} className="text-[11px] font-bold text-[#0071e3] dark:text-[#0A84FF] hover:underline">Edit</button>
                                    ) : (
                                        <button onClick={handleSaveDescription} className="text-[11px] font-bold text-[#0071e3] dark:text-[#0A84FF] hover:underline">Done</button>
                                    )}
                                </div>

                                {isEditingSummary ? (
                                    <textarea 
                                        value={editedSummary}
                                        onChange={(e) => setEditedSummary(e.target.value)}
                                        className="w-full h-[400px] p-4 border border-[#0071e3] dark:border-[#0A84FF] rounded-xl text-[15px] leading-relaxed focus:outline-none bg-white dark:bg-[#2C2C2E] dark:text-[#f5f5f7] font-sans resize-y"
                                    />
                                ) : (
                                    <div className="text-[#424245] dark:text-[#B0B0B5] text-[15px] leading-relaxed whitespace-pre-wrap">
                                        {job.summary}
                                    </div>
                                )}
                            </div>
                        </div>
                    ) : (
                        <div className="animate-in fade-in slide-in-from-bottom-2 duration-300">
                            <div className="flex items-center justify-between mb-6">
                                <h3 className="text-[20px] font-bold text-[#1d1d1f] dark:text-white">Strategy Kit</h3>
                                <button onClick={() => onGenerateKit(job)} className="text-[13px] font-medium text-[#0071e3] dark:text-[#0A84FF] hover:bg-[#f5f5f7] dark:hover:bg-[#2C2C2E] px-4 py-2 rounded-full transition-colors flex items-center gap-2">
                                    <Sparkles size={16} /> Regenerate
                                </button>
                            </div>

                            {analysis?.strategy ? (
                                <div className="prose prose-p:text-[#424245] dark:prose-p:text-[#B0B0B5] prose-headings:text-[#1d1d1f] dark:prose-headings:text-white max-w-none">
                                    <div className="whitespace-pre-wrap leading-relaxed">{analysis.strategy}</div>
                                </div>
                            ) : (
                                <div className="py-20 text-center text-[#86868b] dark:text-[#98989D]">
                                    <Sparkles size={40} className="mx-auto mb-4 animate-pulse text-[#0071e3] dark:text-[#0A84FF]" />
                                    <p className="font-medium">Formulating your custom strategy...</p>
                                </div>
                            )}
                        </div>
                    )}
                </div>

                {/* RIGHT: Properties Panel */}
                <div className="w-full md:w-72 shrink-0 space-y-8 order-1 md:order-2">
                    {/* Status Dropdown */}
                    <div>
                        <label className="text-[10px] font-bold uppercase tracking-wider text-[#86868b] dark:text-[#98989D] mb-2 block">Status</label>
                        <div className="relative">
                            <select 
