        <nav className="fixed top-0 left-0 right-0 h-14 bg-[#1d1d1f]/70 dark:bg-[#1c1c1e]/70 backdrop-blur-xl z-[40] border-b border-white/10 dark:border-white/5 transition-colors duration-300">
            <div className="max-w-[1024px] mx-auto h-full flex items-center justify-between px-6">
                 <div className="flex items-center gap-6">
                     <span className="font-semibold text-base tracking-tight text-[#1d1d1f] dark:text-white flex items-center gap-2 transition-colors"><Layers size={18} /> Career Studio</span>
                     <div className="hidden sm:flex items-center gap-6 text-[#86868b]">
                         <button onClick={() => setCurrentView(ViewState.DASHBOARD)} className={`transition-colors hover:text-black dark:hover:text-white ${currentView === ViewState.DASHBOARD ? 'text-black dark:text-white font-medium' : ''}`}>Discover</button>
                         <button onClick={() => setCurrentView(ViewState.KANBAN)} className={`transition-colors hover:text-black dark:hover:text-white ${currentView === ViewState.KANBAN ? 'text-black dark:text-white font-medium' : ''}`}>Pipeline</button>
                         <button onClick={() => setCurrentView(ViewState.CV_EDITOR)} className={`transition-colors hover:text-black dark:hover:text-white ${currentView === ViewState.CV_EDITOR ? 'text-black dark:text-white font-medium' : ''}`}>Resume</button>
                     </div>
                 </div>

                 <div className="flex items-center gap-4">
                     {analyzingCount > 0 && (
