const ScoreRing = ({ score }: { score: number }) => {
    const radius = 18;
    const stroke = 3;
    const normalizedRadius = radius - stroke * 2;
    const circumference = normalizedRadius * 2 * Math.PI;
    const strokeDashoffset = circumference - (score / 100) * circumference;

    // Apple Activity Ring Colors
    let color = '#34C759'; // Green
    if (score < 50) color = '#FF3B30'; // Red
    else if (score < 75) color = '#FFCC00'; // Yellow

    return (
        <div className="relative w-12 h-12 flex items-center justify-center">
            <svg height={radius * 2} width={radius * 2} className="transform -rotate-90">
                <circle
                    stroke={color}
                    strokeOpacity="0.2"
                    strokeWidth={stroke}
                    fill="transparent"
                    r={normalizedRadius}
                    cx={radius}
                    cy={radius}
                />
                <circle
                    stroke={color}
                    fill="transparent"
                    strokeWidth={stroke}
                    strokeDasharray={circumference + ' ' + circumference}
                    style={{ strokeDashoffset }}
                    strokeLinecap="round"
                    r={normalizedRadius}
                    cx={radius}
                    cy={radius}
                    className="ring-circle"
                />
            </svg>
            <span className="absolute text-[10px] font-bold text-[#1d1d1f] dark:text-white">
                {score}
            </span>
        </div>
    );
};

const JobCard: React.FC<JobCardProps> = ({ job, onOpenDetail, onToggleStatus, onDelete, isKanban }) => {
  const analysis = job.analysis;
  const status = job.status || 'new';
  const isSavedOrBetter = ['saved', 'applied', 'interview', 'offer'].includes(status);

  const getAbsoluteUrl = (url?: string) => {
      if (!url || url === 'Manual Entry') return null;
      return url.startsWith('http') ? url : `https://${url}`;
  };

  const applyUrl = getAbsoluteUrl(job.url) || `https://www.google.com/search?q=${encodeURIComponent(`${job.title} ${job.company} jobs`)}`;

  // Tiny Card for Kanban - Ultra Compact
  if (isKanban) {
      return (
        <div 
            className="apple-card p-4 cursor-pointer flex flex-col gap-2 group"
            onClick={() => onOpenDetail(job)}
        >
            <div className="flex justify-between items-start gap-1">
                <h4 className="font-bold text-[14px] text-[#1d1d1f] dark:text-[#f5f5f7] leading-snug line-clamp-2">
                    {job.title}
                </h4>
            </div>

            <p className="text-[12px] text-[#86868b] dark:text-[#98989D] font-medium truncate">{job.company}</p>

