                     </div>
                 ) : (
                    <span className="text-[10px] text-[#d2d2d7] dark:text-[#555]">No Score</span>
                 )}
                 {job.seniorityScore === 'Senior' && <span className="text-[10px] font-bold text-[#0071e3] dark:text-[#0A84FF]">Senior</span>}
