                {analysis?.isHighValue && (
                     <span className="px-3 py-1 rounded-full text-[12px] font-semibold bg-[#E6F4EA] dark:bg-[#1e3a29] text-[#34C759] flex items-center gap-1"><TrendingUp size={12}/> High Value</span>
                )}
                 {job.seniorityScore && (
