        {/* Scrollable Content */}
        <div className="flex-1 overflow-y-auto custom-scrollbar px-8 pb-12">
            <div className="flex flex-col md:flex-row gap-12">

                {/* LEFT: Main Information */}
                <div className="flex-1 order-2 md:order-1">

                    {/* Tabs Pill */}
